function run() {
  const page = figma.getNodeById("0:1");
  if (!page) {
    return "Page 0:1 not found";
  }
  const textNodes = page.findAll(node => node.type === "TEXT");
  // Let's sort them by their absolute y coordinate to read them in order
  textNodes.sort((a, b) => {
    const ay = a.absoluteTransform[1][2];
    const by = b.absoluteTransform[1][2];
    const ax = a.absoluteTransform[0][2];
    const bx = b.absoluteTransform[0][2];
    if (Math.abs(ay - by) < 15) return ax - bx;
    return ay - by;
  });
  const lines = textNodes.map(t => t.characters);
  return lines.join("\n---\n");
}
